@lru_cache(1024 * 16)
def _split_cells(cls, segment: "Segment", cut: int) -> Tuple["Segment", "Segment"]:
    """Split a segment in to two at a given cell position.

    Note that splitting a double-width character, may result in that character turning
    into two spaces.

    Args:
        segment (Segment): A segment to split.
        cut (int): A cell position to cut on

    Returns:
        A tuple of two segments.
    """
    text, style, control = segment
    _Segment = Segment
    cell_length = segment.cell_length
    if cut >= cell_length:
        return segment, _Segment("", style, control)

    current_pos = 0
    for i, char in enumerate(text):
        char_size = cell_size(char)
        # Check if adding this character exceeds the cut point
        if current_pos + char_size > cut:
            before = text[:current_pos]
            return (_Segment(before, style, control), _Segment(text[current_pos:], style, control))

        current_pos += char_size

    # If we finish the loop without returning, it means cut is at or beyond the end of text.
    return (_Segment(text, style, control), _Segment("", style, control))

